echo count($mapping) . " subgroepen in de mapping.\n\n";

$groupIds = [];
$groupsCreated = 0; $groupsUpdated = 0;
foreach ($mapping as [$pg, $ag]) {
    $key = mb_strtolower($pg);
    if (isset($groupIds[$key])) continue;
    $slug = \Illuminate\Support\Str::limit(\Illuminate\Support\Str::slug($pg), 50, '');
    $group = \App\Models\MachineGroup::withTrashed()->firstOrCreate(
        ['group_number' => $slug],
        ['group_name' => \Illuminate\Support\Str::limit($pg, 150)],
    );
    if ($group->wasRecentlyCreated) $groupsCreated++;
    if ($group->trashed()) $group->restore();
    if ($ag && $group->analysis_group !== $ag) {
        $group->update(['analysis_group' => \Illuminate\Support\Str::limit($ag, 150)]);
        $groupsUpdated++;
    }
    $groupIds[$key] = $group->id;
}
echo "Productgroepen: $groupsCreated nieuw, $groupsUpdated analysegroep bijgewerkt.\n";

$moved = 0; $ok = 0; $missing = 0;
foreach ($mapping as $nr => [$pg, $ag]) {
    $gid = $groupIds[mb_strtolower($pg)];
    $sg = \App\Models\MachineSubgroup::withTrashed()->where('subgroup_number', (string) $nr)->first();
    if (! $sg) { $missing++; continue; }
    if ($sg->trashed()) $sg->restore();
    if ($sg->group_id !== $gid) { $sg->update(['group_id' => $gid]); $moved++; }
    else { $ok++; }
}
echo "Subgroepen: $moved verplaatst naar juiste groep, $ok stonden al goed, $missing niet in db.\n\n";

// Controle
$check = \Illuminate\Support\Facades\DB::table('machine_subgroups as sg')
    ->join('machine_groups as g', 'g.id', '=', 'sg.group_id')
    ->whereNull('sg.deleted_at')->whereNull('g.analysis_group')->count();
echo "Subgroepen zonder analysegroep na herstel: $check\n";

